begin;
select no_plan();
-- These helpers produce synthetic normalized records, never provider payloads.
create function pg_temp.account(p_id text default 'a', p_balance bigint default 100) returns jsonb language sql as $$
select jsonb_build_array(jsonb_build_object('external_id',p_id,'name','Synthetic account','iban_masked','FR00•••••••••••••••0000','currency','EUR','current_balance_cents',p_balance,'available_balance_cents',null,'status','active','updated_at','2026-09-01T12:00:00Z')) $$;
create function pg_temp.tx(p_id text default 't', p_currency text default 'EUR', p_status text default 'pending') returns jsonb language sql as $$
select jsonb_build_array(jsonb_build_object('external_id',p_id,'account_external_id','a','currency',p_currency,'amount_cents',50,'direction','outflow','status',p_status,'label','Synthetic transaction','counterparty',null,'transaction_date','2026-09-01','value_date',null,'updated_at','2026-09-01T12:00:00Z')) $$;
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');
insert into public.app_settings(owner_user_id) values ('10000000-0000-4000-8000-000000000001');
select has_function('public','acquire_banking_sync',array['uuid','uuid']);
select lives_ok($$ select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001') $$,'acquisition succeeds');
select throws_ok($$ select public.acquire_banking_sync('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000099') $$,'42501','DATABASE_ERROR','nonowner denied');
select throws_ok($$ select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002') $$,'P0001','SYNC_LOCKED','second holder denied');
select is((select initial_created_from from public.integrations),((clock_timestamp() at time zone 'Europe/Paris')::date - interval '6 months')::date,'six calendar month initial bound');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,2,null,'[]') $$,'P0001','DATABASE_ERROR','out of order page rejected');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,3,'[]') $$,'P0001','DATABASE_ERROR','invalid next cursor rejected');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,pg_temp.account('valid-first') || pg_temp.account('invalid-second',9007199254740992)) $$,'P0001','DATABASE_ERROR','invalid second record rolls back full page');
select is((select count(*) from public.bank_account_staging),0::bigint,'invalid page leaves no partially staged records');
select is((select count(*) from public.banking_sync_pages),0::bigint,'invalid page does not advance checkpoint');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,jsonb_set(pg_temp.account(),'{0,current_balance_cents}','1.5')) $$,'P0001','DATABASE_ERROR','fractional JSON money rejected');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,jsonb_set(pg_temp.account(),'{0,current_balance_cents}','"100"')) $$,'P0001','DATABASE_ERROR','string JSON money rejected');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,jsonb_set(pg_temp.account(),'{0,updated_at}','"2026-09-01"')) $$,'P0001','DATABASE_ERROR','technical timestamp requires explicit timezone');
select lives_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,pg_temp.account()) $$,'stage first account page');
select is((select count(*) from public.bank_accounts),0::bigint,'staging never publishes accounts');
select lives_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,pg_temp.account()) $$,'exact page replay succeeds');
select is((select count(*) from public.bank_account_staging),1::bigint,'replay does not duplicate staging');
select is((select count(*) from public.banking_sync_pages),1::bigint,'replay does not advance checkpoint');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,1,2,pg_temp.account('a',200)) $$,'P0001','DATABASE_ERROR','changed replay rejected');
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001') $$,'P0001','DATABASE_ERROR','unfinished accounts rejected');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','accounts',null,2,null,'[]');
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001') $$,'P0001','DATABASE_ERROR','missing transaction stream rejected');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','transactions','a',1,2,pg_temp.tx());
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001') $$,'P0001','DATABASE_ERROR','unfinished transactions rejected');
select is((select count(*) from public.bank_transactions),0::bigint,'staging never publishes transactions');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','transactions','a',2,null,'[]');
select is(public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'),'{"created":2,"updated":0}'::jsonb,'full atomic publication counts both object types');
create temp table old_state as select (select id from public.bank_accounts) account_id,(select id from public.bank_transactions) transaction_id,(select last_published_updated_to from public.integrations) watermark;
select is((select count(*) from public.provider_object_mappings),2::bigint,'publication creates mappings');
select is((select count(*) from public.bank_account_staging)+(select count(*) from public.bank_transaction_staging)+(select count(*) from public.banking_sync_pages),0::bigint,'success clears all staging');
select is(public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'),'{"created":2,"updated":0}'::jsonb,'success replay returns persisted counts');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002');
select is((select updated_from from public.sync_runs where id='30000000-0000-4000-8000-000000000002'),(select watermark - interval '5 minutes' from old_state),'incremental overlap exactly five minutes');
select is(public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'),'{"created":2,"updated":0}'::jsonb,'old successful replay safe with new holder');
select is((select lease_run_id from public.integrations),'30000000-0000-4000-8000-000000000002'::uuid,'old replay preserves newer lease');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','accounts',null,1,null,pg_temp.account('a',200));
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','transactions','a',1,null,pg_temp.tx('t','USD','completed'));
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002') $$,'P0001','DATABASE_ERROR','invalid staged currency aborts publication');
select is((select current_balance_cents from public.bank_accounts),100::bigint,'failed publish preserves account');
select is((select status from public.bank_transactions),'pending','failed publish preserves transaction');
select is((select last_published_updated_to from public.integrations),(select watermark from old_state),'failed publish preserves watermark');
select is((select count(*) from public.provider_object_mappings),2::bigint,'failed publish preserves mappings');
select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','PROVIDER_INVALID_RESPONSE',true);
select is((select last_connection_succeeded from public.integrations),true,'connection success survives sync failure');
select is((select count(*) from public.bank_account_staging),0::bigint,'failure clears own staging');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003','accounts',null,1,null,pg_temp.account('a',200));
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003','transactions','a',1,null,pg_temp.tx('t','EUR','completed'));
select is(public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003'),'{"created":0,"updated":2}'::jsonb,'idempotent updates counted');
select is((select id from public.bank_accounts),(select account_id from old_state),'stable account UUID');
select is((select id from public.bank_transactions),(select transaction_id from old_state),'stable transaction UUID');
select is((select status from public.bank_transactions),'completed','transaction updates are published');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000004');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000004','accounts',null,1,null,'[]');
select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000004');
select is((select is_current from public.bank_accounts),false,'absent account leaves current inventory');
select is((select count(*) from public.bank_transactions),1::bigint,'absent account history retained');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005');
select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005','accounts',null,1,null,pg_temp.account());
update public.integrations set lease_expires_at=clock_timestamp()-interval '1 second';
select throws_ok($$ select public.renew_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005') $$,'P0001','SYNC_LOCKED','expired renewal denied');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005','accounts',null,1,null,pg_temp.account()) $$,'P0001','SYNC_LOCKED','expired holder cannot replay page');
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005') $$,'P0001','SYNC_LOCKED','expired holder cannot publish before takeover');
select throws_ok($$ select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005','DATABASE_ERROR',false) $$,'P0001','SYNC_LOCKED','expired holder cannot release before takeover');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000006');
select is((select status from public.sync_runs where id='30000000-0000-4000-8000-000000000005'),'interrupted','expired holder marked interrupted');
select is((select count(*) from public.bank_account_staging),0::bigint,'replacement clears abandoned staging');
select throws_ok($$ select public.stage_banking_page('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005','accounts',null,2,null,'[]') $$,'P0001','SYNC_LOCKED','stale staging denied');
select throws_ok($$ select public.publish_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005') $$,'P0001','SYNC_LOCKED','stale publication denied');
select throws_ok($$ select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000005','DATABASE_ERROR',false) $$,'P0001','SYNC_LOCKED','stale release denied');
select is((select lease_run_id from public.integrations),'30000000-0000-4000-8000-000000000006'::uuid,'new lease survives all stale operations');
select lives_ok($$ select public.renew_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000006') $$,'current holder renews');
select lives_ok($$ delete from auth.users where id='10000000-0000-4000-8000-000000000001' $$,'owner deprovisioning cascades with active lease');
set constraints all immediate;
select is((select count(*) from public.integrations)+(select count(*) from public.sync_runs)+(select count(*) from public.bank_accounts)+(select count(*) from public.bank_transactions)+(select count(*) from public.provider_object_mappings),0::bigint,'all banking rows deleted');

insert into public.app_settings(owner_user_id) values ('10000000-0000-4000-8000-000000000002');
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000007');
-- Simulate an initial import begun on an earlier calendar day, still unpublished.
update public.integrations set initial_created_from='2026-01-01',lease_expires_at=clock_timestamp()-interval '1 second';
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000008');
select is((select initial_created_from from public.sync_runs where id='30000000-0000-4000-8000-000000000008'),'2026-01-01'::date,'retry preserves original history date');
select is((select updated_from from public.sync_runs where id='30000000-0000-4000-8000-000000000008'),'2025-12-31T23:00:00Z'::timestamptz,'retry initial window uses owner timezone');
select throws_ok($$select public.fail_banking_sync('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000008','unsafe diagnostic',true)$$,'P0001','DATABASE_ERROR','only stable error codes may persist');
select public.fail_banking_sync('10000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000008','PROVIDER_AUTH_EXPIRED',false);
select is((select last_connection_succeeded from public.integrations),false,'failed connection recorded separately');
select * from finish();
rollback;
